></span><b>Fièvre jaune</b><i>certificat international de vaccination</i></label></li><li><label><input type="checkbox" data-k="pp3"><span></span><b>Billet retour</b><i>ou de continuation</i></label></li><li><label><input type="checkbox" data-k="pp4"><span></span><b>Hébergement</b><i>adresse de la première nuit</i></label></li><li><label><input type="checkbox" data-k="pp5"><span></span><b>Assurance</b><i>frais médicaux et rapatriement</i></label></li></ul></div><div class="pp-pg"><small>VISAS · ENTRÉES</small><div class="pp-st s1"><div>Aéroport<b>COO</b>Cotonou</div></div><div class="pp-st s2"><div>e-Visa<b>Bénin</b>en ligne</div></div><div class="pp-st s3"><div>Fièvre<b>jaune</b>vaccin</div></div><div class="pp-mrz">P&lt;BEN&lt;&lt;BIENVENUE&lt;AU&lt;BENIN&lt;&lt;&lt;&lt;&lt;&lt;&lt;&lt;&lt;&lt;&lt;&lt;&lt;</div></div></div></section><script>(function(){document.querySelectorAll(".pp input[data-k]").forEach(function(i){try{i.checked=localStorage.getItem("ba-"+i.dataset.k)==="1"}catch(e){}i.addEventListener("change",function(){try{localStorage.setItem("ba-"+i.dataset.k,i.checked?"1":"0")}catch(e){}})})})();</script><script>(function(){function go(){var e=document.querySelectorAll(".op-rv:not(.on)");if(!("IntersectionObserver" in window)){e.forEach(function(x){x.classList.add("on")});return}var o=new IntersectionObserver(function(n){n.forEach(function(x){if(x.isIntersecting){x.target.classList.add("on");o.unobserve(x.target)}})},{threshold:.1});e.forEach(function(x){o.observe(x)})}if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",go);else go()})();</script>

            
                                        
            
            
            
                                        
